CREATE TABLE IF NOT EXISTS gis_identity_activation_certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL, crosswalk_version text NOT NULL, total_features integer NOT NULL, locked_features integer NOT NULL, reviewed_features integer NOT NULL DEFAULT 0, unresolved_features integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'BLOCKED', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), activated_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_gis_activation_cert ON gis_identity_activation_certificates(country_code,crosswalk_version,status);